#include <bits/stdc++.h>
using namespace std;

constexpr int MAXN = 120;
int ar[MAXN], bs[MAXN];

bool dominates(int x1, int y1, int x2, int y2) {
    return x1 >= x2 && y1 >= y2 && (x1 > x2 || y1 > y2);
}

int main() {
    for (int i = 1; i <= 4; ++i)
        scanf("%d %d", &ar[i], &bs[i]);

    int b1 = 0, b2 = 0;
    bool t1 = false, t2 = false;

    int a1 = ar[1], a2 = bs[2];

    if (dominates(a1, a2, ar[3], bs[4])) ++b1;
    if (dominates(ar[3], bs[4], a1, a2)) t1 = true;

    if (dominates(a1, a2, ar[4], bs[3])) ++b1;
    if (dominates(ar[4], bs[3], a1, a2)) t1 = true;

    a1 = ar[2];
    a2 = bs[1];

    if (dominates(a1, a2, ar[3], bs[4])) ++b2;
    if (dominates(ar[3], bs[4], a1, a2)) t2 = true;

    if (dominates(a1, a2, ar[4], bs[3])) ++b2;
    if (dominates(ar[4], bs[3], a1, a2)) t2 = true;

    if (b1 == 2 || b2 == 2)
        printf("Team 1\n");
    else if (t1 && t2)
        printf("Team 2\n");
    else
        printf("Draw\n");

    return 0;
}

