#include <bits/stdc++.h>
using namespace std;

int main() {
    int ar[5], bs[5];

    for (int i = 1; i <= 4; ++i)
        cin >> ar[i] >> bs[i];

    auto wins = [](int x1, int x2, int y1, int y2) {
        return (x1 > y1 && x2 >= y2) || (x1 >= y1 && x2 > y2);
    };

    int b1 = 0, b2 = 0;
    bool t1 = false, t2 = false;

    b1 += wins(ar[1], bs[2], ar[3], bs[4]);
    b1 += wins(ar[1], bs[2], ar[4], bs[3]);
    t1 = wins(ar[3], bs[4], ar[1], bs[2]) ||
         wins(ar[4], bs[3], ar[1], bs[2]);

    b2 += wins(ar[2], bs[1], ar[3], bs[4]);
    b2 += wins(ar[2], bs[1], ar[4], bs[3]);
    t2 = wins(ar[3], bs[4], ar[2], bs[1]) ||
         wins(ar[4], bs[3], ar[2], bs[1]);

    if (b1 == 2 || b2 == 2)
        cout << "Team 1\n";
    else if (t1 && t2)
        cout << "Team 2\n";
    else
        cout << "Draw\n";

    return 0;
}

